content:
.reference sup {
  display: none;
}
.reference /* for Parsoid */ {
	font-size: 70%;
}

/* Hide the brackets for the inline cite */
sup.reference a span {
  display: none;
}

.wst-rh-right, .wst-rh-left {
    flex: 0 0 auto;
}
.wst-rh-center {
    position: relative;
}
.wst-rh-center::after {
    content: "";
    position: absolute;
    left: 5px;
    right: 5px;
    top: 50%;
    height: 0;
    border-top: 1px solid black;
}

._play { width: 100%; border-collapse: collapse; }
._play td {  vertical-align: baseline !important; padding: 0 0 .4em; }

/* name column: as wide as longest name, no wrap — wraps only on narrow screens */
._play td:first-child { width: 1%; white-space: nowrap; }
@media (max-width: 480px) {
	._play td:first-child { white-space: normal; }
}

/* gap after the name: exactly one space (non-breaking, so it never collapses) */
._play td:first-child:after {
	content: "\00A0";
}

